const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const owner = $env.GITHUB_OWNER || 'n8n-io';
const repo = $env.GITHUB_REPO || 'n8n';
const language = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();
const token = $env.GITHUB_TOKEN || '';

return [{
  json: {
    owner,
    repo,
    language: ['EN', 'FR'].includes(language) ? language : 'EN',
    since: since.toISOString(),
    until: now.toISOString(),
    githubApiBase: `https://api.github.com/repos/${owner}/${repo}`,
    githubHeaders: token ? { Authorization: `Bearer ${token}` } : {},
  }
}];

const config = $input.first().json;
const headers = {
  Accept: 'application/vnd.github+json',
  'User-Agent': 'n8n-weekly-dev-summary',
  ...config.githubHeaders,
};

async function getJson(path) {
  const response = await fetch(`${config.githubApiBase}${path}`, { headers });
  if (!response.ok) {
    throw new Error(`GitHub API ${path} failed with ${response.status}: ${await response.text()}`);
  }
  return await response.json();
}

const [commits, closedIssuesRaw, prsRaw] = await Promise.all([
  getJson(`/commits?since=${encodeURIComponent(config.since)}&until=${encodeURIComponent(config.until)}&per_page=100`),
  getJson(`/issues?state=closed&since=${encodeURIComponent(config.since)}&per_page=100`),
  getJson('/pulls?state=closed&sort=updated&direction=desc&per_page=100'),
]);

return [{ json: { ...config, commits, closedIssuesRaw, prsRaw } }];

const config = $input.first().json;
const commits = Array.isArray(config.commits) ? config.commits : [];
const closedIssuesRaw = Array.isArray(config.closedIssuesRaw) ? config.closedIssuesRaw : [];
const prsRaw = Array.isArray(config.prsRaw) ? config.prsRaw : [];
const sinceTime = new Date(config.since).getTime();

const issues = closedIssuesRaw
  .filter(issue => !issue.pull_request)
  .filter(issue => issue.closed_at && new Date(issue.closed_at).getTime() >= sinceTime)
  .slice(0, 30)
  .map(issue => ({
    number: issue.number,
    title: issue.title,
    closed_at: issue.closed_at,
    url: issue.html_url,
  }));

const mergedPulls = prsRaw
  .filter(pr => pr.merged_at && new Date(pr.merged_at).getTime() >= sinceTime)
  .slice(0, 30)
  .map(pr => ({
    number: pr.number,
    title: pr.title,
    merged_at: pr.merged_at,
    author: pr.user?.login,
    url: pr.html_url,
  }));

const commitItems = commits.slice(0, 50).map(commit => ({
  sha: commit.sha?.slice(0, 7),
  message: commit.commit?.message?.split('\n')[0],
  author: commit.commit?.author?.name || commit.author?.login,
  date: commit.commit?.author?.date,
  url: commit.html_url,
}));

const prompt = `You are writing a weekly development summary for ${config.owner}/${config.repo}.\n\nLanguage: ${config.language}.\nPeriod: ${config.since} to ${config.until}.\n\nWrite a concise narrative summary for a developer team. Include:\n- a short headline\n- 3 to 6 bullets grouped by theme\n- merged PR highlights\n- closed issue highlights\n- notable commit themes\n- a short next-week watchlist inferred from the activity\n\nAvoid hype. Be specific. Mention issue/PR numbers where useful.\n\nData:\n${JSON.stringify({ commits: commitItems, closedIssues: issues, mergedPulls }, null, 2)}`;

delete config.commits;
delete config.closedIssuesRaw;
delete config.prsRaw;

return [{
  json: {
    ...config,
    metrics: {
      commitCount: commits.length,
      closedIssueCount: issues.length,
      mergedPullCount: mergedPulls.length,
    },
    prompt,
  }
}];

const config = $('Build Claude Prompt').first().json;
const response = $input.first().json;
const textParts = Array.isArray(response.content)
  ? response.content.filter(part => part.type === 'text').map(part => part.text)
  : [];
const summary = textParts.join('\n\n').trim() || 'Claude returned no text summary.';
const content = `**Weekly dev summary: ${config.owner}/${config.repo}**\n_${config.since.slice(0, 10)} to ${config.until.slice(0, 10)}_\n\n${summary}\n\nMetrics: ${config.metrics.commitCount} commits, ${config.metrics.mergedPullCount} merged PRs, ${config.metrics.closedIssueCount} closed issues.`;
return [{ json: { content } }];
